/// <summary>
/// Nature 30/40 report data service class
/// </summary>
public class METNature3040ReportDataService
{
    METNature3040ReportContract     contract;
    METNature3040ReportsTable       metNature3040ReportsTable;
    Query                           reportQuery;
    Map                             infoTableMap;
    Set                             missingItemSetups; 
    boolean                         isExecutingWithoutFromDate;
    #OCCRetryCount
    METProcMetrics   procMetrics;

    #define.Tariff('001')
    #define.LALSUnit('EA')
    #define.LUnit('L')
    #define.LALSUnit30('L of Alcohol')

}

Method.Source:
/// <summary>
/// parm contract
/// </summary>
/// <param name = "_contract">contract</param>
/// <returns>contract</returns>
public METNature3040ReportContract parmContract(METNature3040ReportContract _contract = null)
{
    if (_contract)
    {
        contract = _contract;
    }
    return contract;
}

/// <summary>
/// generate report data
/// </summary>
/// <returns>True if <c>metNature3040ReportsTable</c> records are inserted; otherwise, false.</returns>
public boolean generateData()
{
    procMetrics = METProcMetricsScope::current();

    if (procMetrics)
    {
        procMetrics.startDescriptionTime(2, "@MET:NAT3040GenData");
    }
    boolean ret = this.generateReportData(true); // Generate report data with date range filter to capture relevant transactions for the report run.

    if (procMetrics)
    {
        procMetrics.endDescriptionTime(2);
    }

    if (procMetrics)
    {
        procMetrics.startDescriptionTime(3, "@MET:NAT3040HistoryRun");
    }

    ret = ret && this.generateReportData(false); // Generate report data without date range filter to capture any late updates to excise information table after the initial run.

    if (procMetrics)
    {
        procMetrics.endDescriptionTime(3);
    }

    return ret;
}

/// <summary>
/// Generates data for the NAT30/NAT40 report by querying the METExciseInformationTable based on the specified criteria, calculating necessary fields, and inserting records into the METNature3040ReportsTable staging table. The method can be executed in two passes: first with a date range filter to capture transactions within the report period, and then without the date range to include any relevant transactions that were updated after the initial data generation. The method returns true if any records were inserted into the staging table; otherwise, it returns false.
/// </summary>
/// <param name = "_applyDateRange">Indicates whether to apply the date range filter.</param>
/// <returns>True if <c>metNature3040ReportsTable</c> records are inserted; otherwise, false.</returns>
public boolean generateReportData(boolean _applyDateRange)
{
    METExciseInformationTable       metExciseInformationTable, metExciseInformationTablePurch;
    METExciseInformationTable       metExciseInformationTableSum;
    METExciseRegisterEntry          metExciseRegisterEntry;
    METTariffItemCodeBase           metTariffItemCodeBase;
    METInventTable                  metInventTable, metInventTableLoc;
    RecordInsertList                recordInsertListTmp = new RecordInsertList(tableNum(metNature3040ReportsTable), false, false, false, false, false, metNature3040ReportsTable);
    TransDateTime                   transDateTime = DateTimeUtil::utcNow();
    Counter                         noOfRecords = 0;     
    container                       calculatedValues;

    boolean                         isReportDataGenerated;

    isExecutingWithoutFromDate = !_applyDateRange;

    METExciseRegisterOriginTypes    originTypes;

    infoTableMap = new Map(Types::Int64, Types::Enum);
    missingItemSetups = new Set(Types::String);

    Query                           query = new Query(this.buildQuery(_applyDateRange));

    query.dataSourceTable(tableNum(METExciseInformationTable)).addGroupByAndSelectionField(fieldNum(METExciseInformationTable, ItemId));

    QueryRun                         queryRun = new QueryRun(query);

    while (queryRun.next())
    {
        try
        {
            ttsbegin;
            metExciseInformationTable = queryRun.get(tableNum(METExciseInformationTable));

            metNature3040ReportsTable.clear();

            metNature3040ReportsTable.ItemId = metExciseInformationTable.ItemId;
            metNature3040ReportsTable.FromDateTime = contract.parmFromDate();
            metNature3040ReportsTable.ToDateTime = contract.parmToDate();   
            metNature3040ReportsTable.SiteId = contract.parmSite();
            metNature3040ReportsTable.Nat3040ReportNumber = contract.parmNat30Number();
            metNature3040ReportsTable.ItemDescription = InventTable::find(metExciseInformationTable.ItemId).itemName();

            select firstonly metTariffItemCodeBase
                exists join metInventTable
                    where metTariffItemCodeBase.RecId == metInventTable.METTariffItemCodeBaseRecid  &&
                        metInventTable.ItemId == metExciseInformationTable.ItemId;

            metNature3040ReportsTable.TariffItem  = metTariffItemCodeBase.TariffItem;
            metNature3040ReportsTable.TariffItemDescription = metTariffItemCodeBase.Description;
            metNature3040ReportsTable.StatCode    = metTariffItemCodeBase.StatCode;
            metNature3040ReportsTable.DutyLAL     = METTariffItemCode::findRecId(metTariffItemCodeBase.RecId).DutyLAL;

            calculatedValues = this.getCasesSold(metExciseInformationTable.ItemId);
            metNature3040ReportsTable.CasesSold = conPeek(calculatedValues, 1);

            metNature3040ReportsTable.LALSQuantity = this.getLALSQty(metExciseInformationTable.ItemId, metTariffItemCodeBase, contract.parmMETNat3040(), metNature3040ReportsTable);

            InventQty originalQty;

            metInventTableLoc =  METInventTable::find(metNature3040ReportsTable.ItemId);

            if (contract.parmMETNat3040() == METNAT3040::NAT30)
            {
                metNature3040ReportsTable.TIUV = conPeek(calculatedValues, 2);

                metNature3040ReportsTable.TariffRate = #Tariff;

                metNature3040ReportsTable.OriginCountryCode   = metInventTableLoc.CountryCode;
                metNature3040ReportsTable.PreferenceRule      = metInventTableLoc.PreferenceRule;
                metNature3040ReportsTable.PreferenceScheme    = metInventTableLoc.PreferenceScheme;
                metNature3040ReportsTable.InvoiceAlcohol      = metInventTableLoc.AlcoholContent;
                metNature3040ReportsTable.LALSUnit = #LALSUnit;

                metNature3040ReportsTable.CustomsValue = conPeek(calculatedValues, 3); // VFD

                if (metInventTableLoc.beerallowance())
                {
                    metNature3040ReportsTable.LQuantity = metInventTableLoc.ItemPack * metInventTableLoc.BottleSize * metNature3040ReportsTable.CasesSold;
                }

                metNature3040ReportsTable.ExciseAmount = metNature3040ReportsTable.LALSQuantity * metNature3040ReportsTable.DutyLAL + (metNature3040ReportsTable.CustomsValue * metInventTableLoc.metGetAdValoremRate());

                metNature3040ReportsTable.LUnit = #LALSUnit30;
                originalQty = metNature3040ReportsTable.LALSQuantity;
            }
            else
            {
                metNature3040ReportsTable.LUnit = #LALSUnit30;
                originalQty = metNature3040ReportsTable.LALSQuantity;
                metNature3040ReportsTable.OriginCountryCode   = metInventTableLoc.CountryCode;
                metNature3040ReportsTable.InvoiceAlcohol      = metInventTableLoc.AlcoholContent;
                metNature3040ReportsTable.ExciseAmount = metNature3040ReportsTable.LALSQuantity * metNature3040ReportsTable.DutyLAL;
            }

            if (originalQty > 0)
            {
                noOfRecords++;
                recordInsertListTmp.add(metNature3040ReportsTable);
            }
            ttscommit;
            this.updateExciseInformationTable(contract, metExciseInformationTable.ItemId);
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    error(strFmt("@MET:METNAT3040Error", metExciseInformationTable.ItemId));
                    this.updateExciseInformationTable(contract, metExciseInformationTable.ItemId, true);
                }
                else
                {
                    retry;
                }
            }
            else
            {
                throw Exception::UpdateConflict;
            }
        }
        catch(Exception::DuplicateKeyException)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    error(strFmt("@MET:METNAT3040Error", metExciseInformationTable.ItemId));
                    this.updateExciseInformationTable(contract, metExciseInformationTable.ItemId, true);
                }
                else
                {
                    retry;
                }
            }
            else
            {
                throw Exception::DuplicateKeyException;
            }
        }
        catch
        {
            error(strFmt("@MET:METNAT3040Error", metExciseInformationTable.ItemId));
            this.updateExciseInformationTable(contract, metExciseInformationTable.ItemId, true);
        }
    }

    if (noOfRecords > 0)
    {
        recordInsertListTmp.insertDatabase();
        isReportDataGenerated = true;
    }

    return isReportDataGenerated;
}

/// Consumes available duty credit for a given item and site before reporting the sale quantity in the NAT30/NAT40 report.
/// Updates the duty credit table by decrementing the credit remaining and marking records as closed when fully used.
/// </summary>
/// <param name="_itemId">The item number being processed in the report.</param>
/// <param name="_siteId">The site associated with the item for duty credit tracking.</param>
/// <param name="_saleQty">The total quantity of the item to be reported before applying duty credits.</param>
/// <returns>
/// The quantity remaining to be reported after applying available duty credits.
/// If full credit is available, this will return zero; otherwise, returns the uncredited portion.
/// </returns>
public static InventQty consumeDutyCredit(ItemId _itemId, InventSiteId _siteId, InventQty _saleQty)
{
    InventQty remainingQty = _saleQty;
    METDutyCreditTable dutyCreditTable;

    while select forupdate dutyCreditTable order by RecId asc
        where dutyCreditTable.ItemId == _itemId &&
          dutyCreditTable.SiteId == _siteId &&
          dutyCreditTable.CreditClosed == NoYes::No
    {
        if (dutyCreditTable.CreditRemaining >= remainingQty)
        {
            dutyCreditTable.CreditRemaining -= remainingQty;

            if (dutyCreditTable.CreditRemaining == 0)
            {
                dutyCreditTable.CreditClosed = NoYes::Yes;
            }

            dutyCreditTable.update();
            remainingQty = 0;
            break;
        }
        else
        {
            remainingQty -= dutyCreditTable.CreditRemaining;
            dutyCreditTable.CreditRemaining = 0;
            dutyCreditTable.CreditClosed = NoYes::Yes;
            dutyCreditTable.update();
        }
    }

    return remainingQty;
}

/// <summary>
/// Get cases sold, TUIV and VFD
/// </summary>
/// <param name = "_exciseInfoTable">exciseTable</param>
/// <returns>container</returns>

public container getTUIVAndVFD(METExciseInformationTable _exciseInfoTable)
{
    InventQty                       casesQtyLodgement, caseQty;
    METTransportInsurance           TUIVLodgement, TUIV;
    METValueForDuty                 VFDLodgement, VFD;
    METExciseRegisterEntry          metExciseRegisterEntry;
    TransDateTime                   minDateTime = DateTimeUtil::minValue();
    InventQty                       itemPackQtyPerLodgement, itemPackQty;
    InventTable                     inventTable = InventTable::find(_exciseInfoTable.ItemId);

    METExciseRegisterReferenceId    exciseRegisterReferenceId;

    METLodgement                    lodgement;
    ReferenceNumber                 referenceNumber;
    InventQty                       lodgementQty;
    TransDateTime                   transDateTime = DateTimeUtil::utcNow();

    List    lodgements = new List(Types::String);
    lodgements = strSplit(_exciseInfoTable.Lodgement, ',');

    ListEnumerator    lodgementEnum = lodgements.getEnumerator();

    while (lodgementEnum.moveNext())
    {
        lodgement = lodgementEnum.current();

        lodgementQty = this.getLodgementQty(_exciseInfoTable, lodgement);
        referenceNumber = this.getReferenceNumber(_exciseInfoTable, lodgement);

        select firstonly validtimestate(transDateTime) metExciseRegisterEntry
            where metExciseRegisterEntry.ItemId      == _exciseInfoTable.ItemId &&
                    metExciseRegisterEntry.SiteId      == _exciseInfoTable.SiteId &&
                    metExciseRegisterEntry.OrderNumber == referenceNumber &&
                    metExciseRegisterEntry.Lodgement   == lodgement;

        if (!metExciseRegisterEntry.RecId)
        {
            select firstonly validtimestate(minDateTime, transDateTime) metExciseRegisterEntry
                where metExciseRegisterEntry.ItemId      == _exciseInfoTable.ItemId &&
                        metExciseRegisterEntry.SiteId      == _exciseInfoTable.SiteId &&
                        metExciseRegisterEntry.OrderNumber == referenceNumber &&
                        metExciseRegisterEntry.Lodgement   == lodgement;

            exciseRegisterReferenceId = metExciseRegisterEntry.ReferenceId;

            metExciseRegisterEntry = null;

            select firstonly validtimestate(transDateTime) metExciseRegisterEntry
                where metExciseRegisterEntry.ReferenceId == exciseRegisterReferenceId;
        }

        itemPackQtyPerLodgement = lodgementQty;

        if (itemPackQtyPerLodgement < 0)
        {
            itemPackQtyPerLodgement = METNature3040ReportDataService::consumeDutyCredit(_exciseInfoTable.ItemId,
                                                                      _exciseInfoTable.SiteId,
                                                                      abs(itemPackQtyPerLodgement));

            if (itemPackQtyPerLodgement == 0 && !infoTableMap.exists(_exciseInfoTable.RecId))
            {
                infoTableMap.insert(_exciseInfoTable.RecId, METNatureReportStatus::DutyCreditDepleted);
            }
            else if (abs(itemPackQtyPerLodgement) > 0 && !infoTableMap.exists(_exciseInfoTable.RecId))
            {
                infoTableMap.insert(_exciseInfoTable.RecId, METNatureReportStatus::PartiallyReported);
            }
        }
        else
        {
            itemPackQtyPerLodgement = -1 * itemPackQtyPerLodgement;
        }

        casesQtyLodgement = UnitOfMeasureConverter::convert(itemPackQtyPerLodgement,
                        UnitOfMeasure::unitOfMeasureIdBySymbol(inventTable.inventUnitId()),
                        UnitOfMeasure::unitOfMeasureIdBySymbol(this.getSalesOrderUnit(_exciseInfoTable.ItemId)),
                        NoYes::Yes,
                        inventTable.Product,
                        NoYes::No);

        if (metExciseRegisterEntry.RecId)
        {
            TUIVLodgement = metExciseRegisterEntry.TIUV * casesQtyLodgement;
            VFDLodgement  = metExciseRegisterEntry.DutyRateReceived * casesQtyLodgement;
        }
        TUIV += TUIVLodgement;
        VFD += VFDLodgement;
        caseQty += casesQtyLodgement;
    }

    return [caseQty, TUIV, VFD];
}

/// <summary>
/// Sales unit
/// </summary>
/// <param name = "_itemId">itemid</param>
/// <returns>SalesUnit</returns>
public METSalesUnit getSalesOrderUnit(ItemId _itemId)
{
    InventItemSalesSetup inventItemSalesSetup;
    InventDim inventDim;
    InventDim inventDimInventItemSalesSetup;

    select firstonly METSalesUnit from inventItemSalesSetup
        exists join inventDimInventItemSalesSetup
        where inventDimInventItemSalesSetup.inventDimId == inventItemSalesSetup.InventDimId
        && inventItemSalesSetup.ItemId == _itemId
        exists join inventDim
        where inventDim.inventDimId == inventDimInventItemSalesSetup.InventDimId
        && inventDim.InventSiteId == inventDimInventItemSalesSetup.InventSiteId;

    return inventItemSalesSetup.METSalesUnit;
}

/// <summary>
/// get LALS Qty
/// </summary>
/// <param name = "_itemId">item</param>
/// <param name = "_metTariffItemCodeBase">TariffCode</param>
/// <param name = "_nat3040">nat3040</param>
/// <param name = "_nature3040ReportsTmp">nature3040</param>
/// <returns>lals</returns>
public InventQty getLALSQty(ItemId                      _itemId,
                            METTariffItemCodeBase       _metTariffItemCodeBase,
                            MetNat3040                  _nat3040,
                            METNature3040ReportsTable   _nature3040ReportsTmp)
{
    InventQty                           itemPackQty;
    InventQty                           lalsQty;
    InventQty                           lalqty;
    InventQty                           totalVFD;
    METExciseSiteDutySetup              metExciseSiteDutySetup;
    METTariffItemCode                   metTariffItemCode = METTariffItemCode::findRecId(_metTariffItemCodeBase.recId);
    METInventTable                      metInventTable = METInventTable::find(_itemId);

    itemPackQty = _nature3040ReportsTmp.CasesSold;

    if (metTariffItemCode.BeerAllowance) //Calculation is same for Nat30 and Nat40
    {
        lalsQty = itemPackQty * metInventTable.ItemPack * metInventTable.BottleSize * (metInventTable.AlcoholContent - metInventTable.metGetAdValoremRate())/100;
    }
    else
    {
        lalsQty = itemPackQty * metInventTable.ItemPack * metInventTable.BottleSize * metInventTable.AlcoholContent/100;
    }

    if (itemPackQty != 0 && lalsQty == 0)
    {
        if (!missingItemSetups.in(_itemId))
        {
            missingItemSetups.add(_itemId);
        }
    }
    return abs(lalsQty);
}

/// <summary>
/// Check if record is valid for report
/// </summary>
/// <param name = "metExciseInformationTable">Excise information table</param>
/// <returns>boolean</returns>
public boolean checkValidRecord(METExciseInformationTable metExciseInformationTable)
{
    METExciseRegisterOriginTypes    originTypes;
    CustomerAttributeValueEntity    customerAttributeValueEntity;
    SalesTable                      salesTable;
    VendParameters                  vendParameters = VendParameters::find();

    if (metExciseInformationTable.InventTransType == InventTransType::InventCounting)
    {
        if (InventCountingReasonCode::find(InventJournalTrans::findInventTransId(metExciseInformationTable.InventTransId).CountingReasonCode).METExemptFromDuty)
        {
            if (!infoTableMap.exists(metExciseInformationTable.RecId))
            {
                infoTableMap.insert(metExciseInformationTable.RecId, METNatureReportStatus::Exempted);
            }
            //Skipping transaction if reason code for counting journal matches with the parameter
            return false;
        }
    }

    select firstonly RecId from originTypes
            where originTypes.ReferenceId == metExciseInformationTable.InventTransType &&
                  originTypes.UpdateNAT3040 == NoYes::Yes &&
            ((metexciseInformationTable.InventoryQty < 0 && originTypes.TransactionType == METTransactionType::Negative) ||
             (metexciseInformationTable.InventoryQty > 0 && originTypes.TransactionType == METTransactionType::Positive));

    if (!originTypes.RecId)
    {
        return false;
    }

    if (metexciseInformationTable.InventTransType == InventTransType::Sales)
    {
        salesTable = salesTable::find(metexciseInformationTable.ReferenceNumber);

        select firstonly BooleanValue from customerAttributeValueEntity
                where customerAttributeValueEntity.AccountNum == salesTable.CustAccount &&
                    customerAttributeValueEntity.AttributeName == vendParameters.METExciseCustomerAttribute;

        if (customerAttributeValueEntity.BooleanValue)
        {
            if (!infoTableMap.exists(metExciseInformationTable.RecId))
            {
                infoTableMap.insert(metExciseInformationTable.RecId, METNatureReportStatus::DutyFree);
            }
            return false;
        }
    }

    return true;
}

/// <summary>
/// update Excise Information Table
/// </summary>
/// <param name = "_contract">contract</param>
public void updateExciseInformationTable(METNature3040ReportContract    _contract, ItemId   _itemId, boolean _isError = false)
{
    #define.prefix('History ')
    Query           query = new Query(reportQuery);

    SysQuery::findOrCreateRange(query.dataSourceTable(tableNum(METExciseInformationTable)), fieldNum(METExciseInformationTable, ItemId)).value(queryValue(_itemId));

    QueryRun        queryRun = new QueryRun(query);

    METExciseRegisterOriginTypes    originTypes;

    str getStatus(ErrorMsg    _value)
    {
        str errorTxt = _value;

        if (isExecutingWithoutFromDate)
        {
            errorTxt = #prefix + errorTxt;
        }

        return errorTxt;
    }

    while (queryRun.next())
    {
        try
        {
            ttsbegin;
            METExciseInformationTable   metExciseInformationTable = queryRun.get(tableNum(METExciseInformationTable));

            metExciseInformationTable.selectForUpdate(true);
            metExciseInformationTable.NAT3040 = _contract.parmMETNat3040();
            metExciseInformationTable.Nat3040ReportNumber = _contract.parmNat30Number();

            if (_isError)
            {
                metExciseInformationTable.NAT3040ReportStatus = getStatus(enum2Str(METNatureReportStatus::Error));
            }
            else
            {
                metExciseInformationTable.Nat3040ReportNumber = _contract.parmNat30Number();
                if (infoTableMap.exists(metExciseInformationTable.RecId))
                {
                    metExciseInformationTable.NAT3040ReportStatus = getStatus(enum2Str(infoTableMap.lookup(metExciseInformationTable.RecId)));
                }
                else
                {
                    if (missingItemSetups.in(metExciseInformationTable.ItemId))
                    {
                        metExciseInformationTable.NAT3040ReportStatus = getStatus(enum2Str(METNatureReportStatus::DataMissing));
                    }
                    else
                    {
                        metExciseInformationTable.NAT3040ReportStatus = getStatus(enum2Str(METNatureReportStatus::Reported));
                    }
                }
            }
            metExciseInformationTable.update();
            ttscommit;
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                throw Exception::UpdateConflict;
            }
        }
        catch(Exception::DuplicateKeyException)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::DuplicateKeyExceptionNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                throw Exception::DuplicateKeyException;
            }
        }
    }
}

/// <summary>
/// Get cases sold
/// </summary>
/// <param name = "_itemId">item id</param>
/// <returns>CasesSold/TUIV/VFD</returns>
public container getCasesSold(ItemId                      _itemId)
{
    METExciseInformationTable           metexciseInformationTable;
    METExciseRegisterOriginTypes        originTypes;
    InventQty                           caseQtyPerItem;
    InventTable                         inventTable = InventTable::find(_itemId);
    Query                               query = new Query(reportQuery);
    QueryBuildDataSource                qbds = query.dataSourceTable(tableNum(METExciseInformationTable));
    boolean                             validRecord = true;



    METTransportInsurance           TUIV;
    METValueForDuty                 VFD;
    container                       CASETUIVVFD;
    VendParameters                  vendParameters = VendParameters::find();
    SalesTable                      salesTable;

    qbds.addRange(fieldNum(METExciseInformationTable, ItemId)).value(queryValue(_itemId));

    qbds.addAllFields(tableStr(METExciseInformationTable));

    QueryRun                            queryRun = new QueryRun(query);

    while (queryRun.next())
    {
        if (procMetrics)
        {
            procMetrics.incLineCount();
        }
        metExciseInformationTable = queryRun.get(tableNum(METExciseInformationTable));

        if (!this.checkValidRecord(metExciseInformationTable))
        {
            continue;
        }

        if (procMetrics)
        {
            procMetrics.incProcessedCount();
        }

        CASETUIVVFD = this.getTUIVAndVFD(metExciseInformationTable);
        caseQtyPerItem += conPeek(CASETUIVVFD, 1);
        TUIV += conPeek(CASETUIVVFD,2);
        VFD += conPeek(CASETUIVVFD, 3);
    }

    if (caseQtyPerItem < 0)
    {
        caseQtyPerItem = 0;
    }

    return [caseQtyPerItem, TUIV, VFD];
}

/// <summary>
/// seting global report query variable
/// </summary>
/// <param name = "_reportQuery">query</param>
/// <returns>query</returns>
public Query setReportQuery(Query    _reportQuery)
{
    reportQuery = _reportQuery;
    return reportQuery;
}

/// <summary>
/// get data query
/// </summary>
/// <returns>query</returns>
public Query buildQuery(boolean  _applyDateRange = true)
{
    METExciseRegisterOriginTypes    originTypes;
    str                             range;
    QueryBuildRange                 buildRangeTransType, rangeRangeQty;;

    Query                           query = new Query();
    query.addDataSource(tableNum(METExciseInformationTable));

    QueryBuildDataSource            qbds = query.dataSourceTable(tableNum(METExciseInformationTable));
    qbds.name('METExciseInformationTable');

    QueryBuildDataSource            qbdsMetItemTable = qbds.addDataSource(tableNum(METInventTable));
    qbdsMetItemTable.relations(false);
    qbdsMetItemTable.addLink(fieldNum(METExciseInformationTable, ItemId), fieldNum(METInventTable, ItemId));
    qbdsMetItemTable.joinMode(JoinMode::ExistsJoin);

    QueryBuildDataSource            qbdsTariffCode = qbdsMetItemTable.addDataSource(tableNum(METTariffItemCodeBase));
    qbdsTariffCode.relations(false);
    qbdsTariffCode.addLink(fieldNum(METInventTable, METTariffItemCodeBaseRecid), fieldNum(METTariffItemCodeBase, RecId));
    qbdsTariffCode.joinMode(JoinMode::ExistsJoin);

    qbdsTariffCode.addRange(fieldNum(METTariffItemCodeBase, NAT3040)).value(queryValue(contract.parmMETNat3040()));

    if (contract.parmNat30Number())
    {
        utcdatetime fromDateTime;
        UtcDateTime toDateTime;
        if (_applyDateRange)
        {
            fromDateTime = contract.parmFromDate();
        }
        else
        {
            fromDateTime = DateTimeUtil::minValue();
        }

        if (_applyDateRange)
        {
            toDateTime = contract.parmToDate();
        }
        else
        {
            toDateTime = DateTimeUtil::addSeconds(contract.parmFromDate(), -1);
        }

        qbds.addRange(fieldNum(METExciseInformationTable, CreatedDateTime)).value(SysQuery::range(fromDateTime, toDateTime));

        if (contract.parmSite())
        {
            qbds.addRange(fieldNum(METExciseInformationTable, SiteId)).value(SysQuery::value(contract.parmSite()));
        }

        while select originTypes
            where originTypes.UpdateNAT3040 == NoYes::Yes
        {
            qbds.addRange(fieldNum(METExciseInformationTable, InventTransType)).value(queryValue(originTypes.ReferenceId));
        }
    }

    qbds.addRange(fieldNum(METExciseInformationTable, Lodgement)).value(SysQuery::valueNotEmptyString());

    this.setReportQuery(query);

    return query;
}

/// <summary>
/// get reference number
/// </summary>
/// <param name = "exciseInformationTable">exciseInfomationTable</param>
/// <param name = "_lodgementId">lodgementId</param>
/// <returns>referenceNumber</returns>
public ReferenceNumber getReferenceNumber(METExciseInformationTable  exciseInformationTable, METLodgement       _lodgementId)
{
    int i;
    container con = exciseInformationTable.LodgementAndQtyCon;

    i = conFind(con, _lodgementId);

    ReferenceNumber  referenceNumber = conPeek(con, i + 2);

    return referenceNumber;
}

/// <summary>
/// get lodgement qty
/// </summary>
/// <param name = "exciseInformationTable">exciseInfoTable</param>
/// <param name = "lodgement">lodgment Id</param>
/// <returns>lodgementQty</returns>
public InventQty getLodgementQty(METExciseInformationTable  exciseInformationTable, METLodgement  lodgement)
{

    int i;

    InventQty       lodgementQty;
    container       con = exciseInformationTable.LodgementAndQtyCon;

    i = conFind(con, lodgement);

    lodgementQty = conPeek(con, i + 1);

    if (exciseInformationTable.InventoryQty < 0)
    {
        if (lodgementQty > 0)
        {
            return lodgementQty * -1;
        }
        else
        {
            return lodgementQty;
        }
    }
    else
    {
        if (lodgementQty < 0 )
        {
            return lodgementQty * -1;
        }
        else
        {
            return lodgementQty;
        }
    }

}
